#!/usr/bin/env python3
"""Customizes the android/ project generated by `npx cap add android`.

Runs in CI after `cap add android`. It must stay idempotent and must NEVER change
the app id or signing key, or installed apps can't be updated.
"""
import glob, os, re, shutil

APP = 'android/app'
RES = f'{APP}/src/main/res'

# 1. Keyboard opens on launch, and the page resizes above it.
mf = f'{APP}/src/main/AndroidManifest.xml'
s = open(mf).read()
s = re.sub(r'\s+android:windowSoftInputMode="[^"]*"', '', s)
s = s.replace('android:name=".MainActivity"',
              'android:name=".MainActivity"\n            android:windowSoftInputMode="adjustResize|stateAlwaysVisible"', 1)
assert 'stateAlwaysVisible' in s, 'manifest patch failed'
open(mf, 'w').write(s)

# 2. Icons, colors, splash. Remove the stock Capacitor splash images first.
for f in glob.glob(f'{RES}/drawable*/splash.png'):
    os.remove(f)
for src in glob.glob('native/res/**/*', recursive=True):
    if os.path.isfile(src):
        dst = os.path.join(RES, os.path.relpath(src, 'native/res'))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copyfile(src, dst)

st = f'{RES}/values/styles.xml'
s = open(st).read()
if 'windowSplashScreenBackground' not in s:
    s = s.replace('<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">',
                  '<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">\n'
                  '        <item name="windowSplashScreenBackground">@color/facts_bg</item>', 1)
    assert 'facts_bg' in s, 'styles patch failed'
    open(st, 'w').write(s)

# 3. Version + release signing. A second android {} block overrides the template's values.
bg = f'{APP}/build.gradle'
s = open(bg).read()
if 'FACTS_SIGNING' not in s:
    s += '''
// FACTS_SIGNING: added by scripts/prepare-android.py
android {
    defaultConfig {
        versionCode((System.getenv("FACTS_VERSION_CODE") ?: "1").toInteger())
        versionName(System.getenv("FACTS_VERSION_NAME") ?: "dev")
    }
    signingConfigs {
        release {
            storeFile rootProject.file("../signing/facts-release.p12")
            storeType "pkcs12"
            storePassword System.getenv("FACTS_KEYSTORE_PASSWORD")
            keyAlias "facts"
            keyPassword System.getenv("FACTS_KEYSTORE_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.release
        }
    }
}
'''
    open(bg, 'w').write(s)
print('android/ customized')
